import { dbank_backend } from "../../declarations/dbank_backend";

async function updateBalance() {
  const currentAmount = await dbank_backend.checkBalance();
  document.getElementById("value").innerText =
    Math.round(currentAmount * 100) / 100;
}

window.addEventListener("DOMContentLoaded", updateBalance);

document.querySelector("form").addEventListener("submit", async function (event) {
  event.preventDefault();

  const button = event.target.querySelector("#submit-btn");
  const inputAmount = parseFloat(document.getElementById("input-amount").value);
  const outputAmount = parseFloat(document.getElementById("withdrawal-amount").value);

  button.setAttribute("disabled", true);

  if (!isNaN(inputAmount)) {
    await dbank_backend.topUP(inputAmount);
  }
  if (!isNaN(outputAmount)) {
    await dbank_backend.withdraw(outputAmount);
  }

  await dbank_backend.compound();
  await updateBalance();

  document.getElementById("input-amount").value = "";
  document.getElementById("withdrawal-amount").value = "";
  button.removeAttribute("disabled");
});

persistent actor DBank {
  stable var currentValue : Float = 300;
  stable var startTime = Time.now();

  public func topUP(amount : Float) { currentValue += amount; };

  public func withdraw(amount : Float) {
    if ((currentValue - amount) >= 0) { currentValue -= amount; }
    else { Debug.print("Amount too large"); };
  };

  public query func checkBalance() : async Float { return currentValue; };

  public func compound() {
    let currentTime = Time.now();
    let timeElapsedS = (currentTime - startTime) / 1000000000;
    currentValue := currentValue * (1.0001 ** Float.fromInt(timeElapsedS));
    startTime := currentTime;
  };
};

